const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Original intersection map: each interval uses the same56-unit scale on both axes.
export function repeatDeliveryMap(source,trace=null,{description=source.pictureText}={}){
 if(source.drawingVersion!==1)return `<div class="repeat-picture-fallback"><p>This saved map-picture version is unavailable.</p><p>${esc(source.pictureText)}</p><p>${esc(description)}</p></div>`;
 const x=n=>44+n*56,y=n=>304-n*56;
 const grid=Array.from({length:6},(_,i)=>`<path d="M${x(i)} 24V304M44 ${y(i)}H324"/><text x="${x(i)}" y="327" text-anchor="middle">${i}</text><text x="26" y="${y(i)+6}" text-anchor="middle">${i}</text>`).join('');
 const points=trace?.points||[],last=points.at(-1);
 return `<svg class="repeat-map-diagram" viewBox="0 0 360 364" role="img" aria-label="${esc(description)}" focusable="false"><g class="repeat-grid">${grid}</g><text class="repeat-axis" x="180" y="352" text-anchor="middle">x · across →</text><text class="repeat-axis" x="11" y="18">y ↑</text>${points.length>1?`<polyline class="repeat-travelled-path" points="${points.map(p=>`${x(p.x)},${y(p.y)}`).join(' ')}"/>`:''}${source.marks.map(role=>{const p=source.places[role.id];return `<g data-repeat-landmark="${role.id}" data-x="${p.x}" data-y="${p.y}">${role.id===source.to?`<rect class="repeat-target-ring" x="${x(p.x)-21}" y="${y(p.y)-21}" width="42" height="42" rx="4"/>`:''}${role.id===source.from?`<circle class="repeat-start-ring" cx="${x(p.x)}" cy="${y(p.y)}" r="21"/>`:''}<circle class="repeat-landmark-dot" cx="${x(p.x)}" cy="${y(p.y)}" r="15"/><text class="repeat-landmark-symbol" x="${x(p.x)}" y="${y(p.y)+6}" text-anchor="middle"${role.symbol.length>2?' textLength="25" lengthAdjust="spacingAndGlyphs"':''}>${esc(role.symbol)}</text></g>`;}).join('')}${last?`<circle class="repeat-courier" cx="${x(last.x)}" cy="${y(last.y)}" r="25" data-repeat-courier-x="${last.x}" data-repeat-courier-y="${last.y}"/>`:''}</svg>`;
}
